+        {
+            if (text[i] is '.' or '!' or '?' && (i + 1 >= text.Length || char.IsWhiteSpace(text[i + 1])))
+            {
+                var sentence = text[start..(i + 1)].Trim();
+                if (sentence.Length > 0)
